<script setup>
import {ref,computed,defineAsyncComponent,nextTick,onBeforeUnmount} from 'vue';
import {Code2,FileCode2,Plus,X,Play,Pause,Check,Download,RotateCcw,ChevronRight,LoaderCircle,Terminal,Layers} from 'lucide-vue-next';
import {makeWorkspace,normalizeWorkspace,writeCodeFiles,codeHash,codePath,snapshotCode} from '../code/workspace.js';import {bundleCode} from '../code/compiler.js';import {SCENE_API,FRONTEND_API} from '../code/api.js';import {downloadBlob,makeZip} from '../../studio/export.js';
const SpatialScene=defineAsyncComponent(()=>import('./SpatialScene.vue')),FrontendCode=defineAsyncComponent(()=>import('./FrontendCode.vue'));
const props=defineProps({node:Object,theme:Object,assets:Object});const emit=defineEmits(['apply','cancel']);const draft=ref(JSON.parse(JSON.stringify(props.node))),workspace=ref(normalizeWorkspace(props.node.props.codeWorkspace)||makeWorkspace(props.node.type==='custom'?'frontend':'scene'));draft.value.props.codeWorkspace=workspace.value;draft.value.props.showHUD=false;const scene=computed(()=>props.node.type!=='custom');
if(!workspace.value.files.length)workspace.value.files=[{path:'main.js',content:scene.value?'export function build(THREE, ctx) {\n  const root = new THREE.Group();\n  // 在此创建几何体、材质、粒子和交互。\n  return { root };\n}\n':'export function mount(root, ctx) {\n  // 自由构建 HTML、SVG 或 Canvas，并接入 ctx.data。\n  root.textContent = "从代码开始，创造自己的组件。";\n}\n'}];
const path=ref(workspace.value.files[0].path),file=computed(()=>workspace.value.files.find(f=>f.path===path.value)),newPath=ref(''),parameters=ref(JSON.stringify(workspace.value.parameters,null,2)),entry=ref(workspace.value.entry),preview=ref(),running=ref(false),playing=ref(true),diagnostics=ref([]),stats=ref(null),tab=ref('output'),showApi=ref(false);let alive=true,runId=0;
const lines=computed(()=>file.value?.content.split('\n').length||1),dirty=computed(()=>codeHash(workspace.value.files)!==codeHash(workspace.value.activeFiles)||entry.value!==workspace.value.activeEntry||parameters.value!==JSON.stringify(workspace.value.activeParameters||{},null,2)||workspace.value.mode!==workspace.value.activeMode);
function addFile(){try{const p=codePath(newPath.value.trim());if(workspace.value.files.some(f=>f.path===p))throw Error('文件已存在');writeCodeFiles(workspace.value,[{path:p,content:''}]);path.value=p;newPath.value='';}catch(e){diagnostics.value=[{state:'error',message:e.message}];}}
function removeFile(){snapshotCode(workspace.value,'删除前');workspace.value.files=workspace.value.files.filter(f=>f.path!==path.value);path.value=workspace.value.files[0]?.path||'';}
async function run(){if(running.value)return;const serial=++runId;running.value=true;diagnostics.value=[];stats.value=null;try{const parsed=JSON.parse(parameters.value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error('参数必须为 JSON 对象');if(workspace.value.activeFiles.length&&dirty.value){workspace.value.checkpoints=[...workspace.value.checkpoints,{id:crypto.randomUUID(),label:'上次成功运行',files:JSON.parse(JSON.stringify(workspace.value.activeFiles)),entry:workspace.value.activeEntry||workspace.value.entry,mode:workspace.value.activeMode||workspace.value.mode,parameters:JSON.parse(JSON.stringify(workspace.value.activeParameters||{}))}].slice(-3);}const next=normalizeWorkspace({...workspace.value,entry:entry.value,parameters:parsed});bundleCode(next.files,next.entry,{target:scene.value?'scene':'frontend',instrument:true});next.activation=crypto.randomUUID();next.activeFiles=JSON.parse(JSON.stringify(next.files));next.activeEntry=next.entry;next.activeMode=next.mode;next.activeParameters=JSON.parse(JSON.stringify(parsed));next.enabled=true;workspace.value=next;draft.value.props.codeWorkspace=next;await nextTick();const hash=codeHash(next.activeFiles),start=performance.now();while(alive&&serial===runId&&performance.now()-start<15000){const el=preview.value?.querySelector('[data-code-state]');if(el?.dataset.codeHash===hash){if(el.dataset.codeState==='error')throw Error(el.dataset.codeError);if(el.dataset.codeState==='ready'){stats.value=JSON.parse(el.dataset.codeStats||'{}');diagnostics.value=[{state:'ready',message:'编译与实际预览通过。源码、参数和交互均保存在当前组件。'},...(stats.value.logs||[]).map(message=>({state:'log',message}))];return;}}await new Promise(r=>setTimeout(r,80));}throw Error('等待代码运行超时');}catch(e){diagnostics.value=[{state:'error',message:e.message}];}finally{if(alive)running.value=false;}}
function restore(c){snapshotCode(workspace.value,'恢复前');Object.assign(workspace.value,{files:JSON.parse(JSON.stringify(c.files)),entry:c.entry,mode:c.mode,parameters:JSON.parse(JSON.stringify(c.parameters))});entry.value=c.entry;parameters.value=JSON.stringify(c.parameters,null,2);path.value=workspace.value.files[0]?.path||'';diagnostics.value=[{state:'log',message:'文件已恢复，点击运行验证。'}];}
async function exportCode(){try{const files=workspace.value.files.map(f=>({name:f.path,content:f.content}));files.push({name:'astra-code.json',content:JSON.stringify({entry:entry.value,target:scene.value?'scene':'frontend',mode:workspace.value.mode,parameters:JSON.parse(parameters.value)},null,2)});downloadBlob(makeZip(files),'astra-frontend-code.zip');}catch(e){diagnostics.value=[{state:'error',message:e.message}];}}
function apply(){if(running.value)return;if(dirty.value){diagnostics.value=[{state:'error',message:'请先运行当前修改，通过后再应用。'}];return;}if(diagnostics.value.some(d=>d.state==='error'))return;emit('apply',JSON.parse(JSON.stringify(workspace.value)));}
onBeforeUnmount(()=>{alive=false;runId++;});
</script>
<template><div class="ace-backdrop"><section class="ace-editor" role="dialog" aria-modal="true" aria-label="前端代码工作区" @keydown.esc.stop="emit('cancel')"><header class="ace-header"><span class="ace-brand"><Code2 :size="19"/></span><div><strong>Code Studio <small>FRONTEND WORKSPACE</small></strong><span>{{node.name}} · {{scene?'Three.js / GLSL':'HTML / CSS / SVG / Canvas'}}</span></div><button class="ace-text" @click="showApi=!showApi">接口说明</button><button class="ace-text" @click="exportCode"><Download :size="13"/>源码</button><button class="ace-run" :disabled="running" @click="run"><component :is="running?LoaderCircle:Play" :class="{spin:running}" :size="13"/>{{running?'验证中':'运行预览'}}</button><button class="ace-apply" :disabled="running||dirty||!workspace.activeFiles.length||diagnostics.some(d=>d.state==='error')" @click="apply"><Check :size="13"/>应用</button><button class="ace-icon" aria-label="关闭代码工作区" @click="emit('cancel')"><X :size="17"/></button></header>
<div class="ace-body"><aside class="ace-files"><label>EXPLORER <span>{{workspace.files.length}} FILES</span></label><button v-for="f in workspace.files" :key="f.path" class="ace-file" :class="{active:path===f.path}" @click="path=f.path"><FileCode2 :size="13"/><span>{{f.path}}</span><i v-if="!workspace.activeFiles.some(a=>a.path===f.path&&a.content===f.content)"></i></button><form class="ace-add" @submit.prevent="addFile"><input v-model="newPath" aria-label="新增代码文件路径" placeholder="新文件，如 lib/math.js"/><button aria-label="新增代码文件"><Plus :size="14"/></button></form><div class="ace-file-settings"><label>ENTRY POINT<input v-model="entry" aria-label="代码入口文件"/></label><label v-if="scene">场景组合<select v-model="workspace.mode" aria-label="代码场景组合方式"><option value="overlay">加入当前场景</option><option value="replace">替换基础场景</option></select></label><button v-if="file" class="ace-delete" @click="removeFile">删除当前文件</button></div><div class="ace-checkpoints"><label>CHECKPOINTS</label><button v-for="c in [...workspace.checkpoints].reverse()" :key="c.id" @click="restore(c)"><RotateCcw :size="11"/>{{c.label}}</button></div></aside>
<main class="ace-code"><div class="ace-filebar"><FileCode2 :size="13"/><span>{{path||'选择或创建一个文件'}}</span><small>{{dirty?'有未运行的修改':'与预览一致'}}</small></div><div class="ace-source" v-if="file"><pre aria-hidden="true">{{Array.from({length:lines},(_,i)=>i+1).join('\n')}}</pre><textarea v-model="file.content" aria-label="源代码编辑器" spellcheck="false" @scroll="$event.target.previousElementSibling.scrollTop=$event.target.scrollTop" autocapitalize="off" autocomplete="off" @keydown.tab.prevent="e=>{const t=e.target,a=t.selectionStart,b=t.selectionEnd;file.content=file.content.slice(0,a)+'  '+file.content.slice(b);nextTick(()=>t.selectionStart=t.selectionEnd=a+2)}"></textarea></div><div class="ace-console"><nav><button :class="{active:tab==='output'}" @click="tab='output'"><Terminal :size="12"/>执行反馈</button><button :class="{active:tab==='parameters'}" @click="tab='parameters'">参数 JSON</button><span v-if="stats">{{stats.objects||0}} 节点 · {{stats.drawCalls||0}} 绘制 · {{stats.vertices||0}} 顶点</span></nav><textarea v-if="tab==='parameters'" v-model="parameters" aria-label="代码组件参数 JSON" spellcheck="false"></textarea><div v-else class="ace-diagnostics"><p v-if="!diagnostics.length">修改源码后运行；错误将返回到这里，原稿保持不变。</p><pre v-for="(d,i) in diagnostics" :key="i" :class="d.state">{{d.message}}</pre></div></div></main>
<div class="ace-preview-pane"><header><span><i></i>LIVE PREVIEW</span><button :aria-label="playing?'暂停代码预览':'播放代码预览'" @click="playing=!playing"><component :is="playing?Pause:Play" :size="13"/></button></header><div ref="preview" class="ace-preview" :style="{'--aw-accent':theme.accent,'--aw-muted':theme.muted}"><SpatialScene v-if="scene" :node="draft" :theme="theme" :assets="assets" :playing="playing" :interactive="true"/><FrontendCode v-else :node="draft" :rows="draft.data.rows" :theme="theme" :playing="playing" :interactive="true"/></div><footer>独立代码运行环境 · 保留原稿 · 应用后可撤销</footer><div v-if="showApi" class="ace-api"><button aria-label="关闭代码接口说明" @click="showApi=false"><X :size="14"/></button><h3>运行接口</h3><pre>{{JSON.stringify(scene?SCENE_API:FRONTEND_API,null,2)}}</pre></div></div></div></section></div></template>
<style src="./code-editor.css"></style>
